/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    SqlDictionary           sqlDictionaryItem;
    SqlDictionary           sqlDictionaryProduct;
    DictTable               dictTable;
    str                     res;

    while select sqlDictionaryItem
        where sqlDictionaryItem.name == 'ItemId'
            join sqlDictionaryProduct
                where sqlDictionaryProduct.tabId == sqlDictionaryItem.tabId
                   && sqlDictionaryProduct.name == 'Product'
    {

        dictTable = new DictTable(sqlDictionaryItem.tabId);
        if(!dictTable.isView())
        {
            if (res != '')
            {
                res += '\n';
            }
            res  +=  int2str(sqlDictionaryItem.tabId) + ' ' +  dictTable.name();
        }
    }

    info(res);
}
